SELECT id, service, host, log_ts, level, payload_json, context, COALESCE(context['region'], 'direct') AS region_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, CAST((status_code & 1) != 0 AS INT) AS has_fault FROM app_logs
